    Bug 1616753 - Fix Gloda filtering when using the filterNode dropdown select. r=tobyp

    - Use the Gobal Search to search something.
    - Click on the "Attachments" filter.
    - Change the select dropdown to something else.
    - CLick on the "Attachments" fiulter again.
    - Ensure the filters are cleared the results page returns to the original state.

    Gloda doesn't have any tests and this section will be deprecated after the Panorama database.
    So this is a quick fix to remove a small annoiance that might affect users until next ESR.

    Differential Revision: https://phabricator.services.mozilla.com/D315749

diff --git a/mail/base/content/widgets/glodaFacet.js b/mail/base/content/widgets/glodaFacet.js
index 42f7309b363..ccd98500d43 100644
--- a/mail/base/content/widgets/glodaFacet.js
+++ b/mail/base/content/widgets/glodaFacet.js
@@ -441,9 +441,7 @@
         return;
       }

-      while (this.filterNode.hasChildNodes()) {
-        this.filterNode.lastChild.remove();
-      }
+      this.filterNode.replaceChildren();

       const allNode = document.createElement("option");
       allNode.textContent = glodaFacetStrings.GetStringFromName(
@@ -501,7 +499,10 @@
     checkStateChanged() {
       // if they un-check us, revert our value to all.
       if (!this.checked) {
+        this.filterNode.selectedIndex = 0;
+        this.filterNode.value = "all";
         this.selectedValue = "all";
+        this.#triggerFacet(this.trueGroups);
       }
     }

@@ -511,24 +512,28 @@
       }
       if (this.filterNode.value == "all") {
         this.selectedValue = "all";
-        FacetContext.addFacetConstraint(
-          this.faceter,
-          true,
-          this.trueGroups,
-          false,
-          true
-        );
-      } else {
-        const groupValue = this.realTrueGroups[parseInt(this.filterNode.value)];
-        this.selectedValue = groupValue.category;
-        FacetContext.addFacetConstraint(
-          this.faceter,
-          true,
-          [groupValue],
-          false,
-          true
-        );
+        this.#triggerFacet(this.trueGroups);
+        return;
       }
+
+      const groupValue = this.realTrueGroups[parseInt(this.filterNode.value)];
+      this.selectedValue = groupValue.category;
+      this.#triggerFacet([groupValue]);
+    }
+
+    /**
+     * Trigger the refresh of the Gloda facet view with updated filters.
+     *
+     * @param {Array} groupValue - Array of boolean explicit filtering.
+     */
+    #triggerFacet(groupValue) {
+      FacetContext.addFacetConstraint(
+        this.faceter,
+        true,
+        groupValue,
+        false,
+        true
+      );
     }
   }

